package com.ecole.gestion_scolaire.hr.controller; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.enums.*; import com.ecole.gestion_scolaire.hr.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/hr/employees") public class EmployeeController { private final EmployeeService service; private final EmployeeProfileService profile; public EmployeeController(EmployeeService s,EmployeeProfileService p){service=s;profile=p;} @GetMapping @PreAuthorize("hasAuthority('PERSONNEL_CONSULTER')") public List<EmployeeResponse> all(){return service.all();} @GetMapping("/{id}") @PreAuthorize("hasAuthority('PERSONNEL_CONSULTER')") public EmployeeResponse one(@PathVariable Long id){return service.one(id);} @PostMapping @PreAuthorize("hasAuthority('PERSONNEL_CREER')") public ResponseEntity<EmployeeResponse> create(@Valid @RequestBody EmployeeRequest q){return ResponseEntity.status(201).body(service.create(q));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public EmployeeResponse update(@PathVariable Long id,@Valid @RequestBody EmployeeRequest q){return service.update(id,q);} @PatchMapping("/{id}/status/{status}") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public void status(@PathVariable Long id,@PathVariable EmploymentStatus status){service.changeStatus(id,status);} @GetMapping("/{id}/profile") @PreAuthorize("hasAuthority('PERSONNEL_CONSULTER')") public Map<String,Object> profile(@PathVariable Long id){return profile.profile(id);} @PostMapping("/{id}/qualifications") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public Object qualification(@PathVariable Long id,@Valid @RequestBody QualificationRequest q){return profile.addQualification(id,q);} @PostMapping("/{id}/history") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public Object history(@PathVariable Long id,@Valid @RequestBody HistoryRequest q){return profile.addHistory(id,q);} @PostMapping("/{id}/contracts") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public Object contract(@PathVariable Long id,@Valid @RequestBody ContractRequest q){return profile.addContract(id,q);} @PostMapping("/{id}/emergency-contacts") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public Object contact(@PathVariable Long id,@Valid @RequestBody EmergencyContactRequest q){return profile.addContact(id,q);} @PostMapping("/{id}/documents") @PreAuthorize("hasAuthority('PERSONNEL_MODIFIER')") public Object document(@PathVariable Long id,@Valid @RequestBody AdminDocumentRequest q){return profile.addDocument(id,q);} @PostMapping("/{id}/notes") @PreAuthorize("hasAuthority('PERSONNEL_NOTES_GERER')") public Object note(@PathVariable Long id,@Valid @RequestBody StaffNoteRequest q){return profile.addNote(id,q);} }